"""Generate committed static entry pages; GitHub Pages needs no build step."""
import json
from html import escape
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
ORIGIN = "https://unpixelated-ideas.github.io/goosechoose/"
IMAGE = ORIGIN + "previewimage.png"
locales = json.loads((ROOT / "app/locales.json").read_text())
shell = (ROOT / "app/shell.html").read_text()
# Resolve assets against this script, so history changes and file:// both work.
(ROOT / "app/shell.js").write_text(
    "// Generated by scripts/build-pages.py; edit app/shell.html.\n"
    "(() => {\n  const base = new URL('.', document.currentScript.src);\n"
    "  const template = document.createElement('template');\n"
    "  template.innerHTML = " + json.dumps(shell, ensure_ascii=False) + ";\n"
    "  template.content.querySelectorAll('img[src]').forEach(img => {\n"
    "    img.src = new URL(img.getAttribute('src'), base).href;\n  });\n"
    "  document.body.append(template.content);\n})();\n"
)
(ROOT / "app/locales.js").write_text(
    "// Generated by scripts/build-pages.py; edit app/locales.json.\n"
    "window.GooseChooseLocales = " + json.dumps(locales, ensure_ascii=False, indent=2) + ";\n"
)
for route, language, assets in [
    ("index.html", "en", "app/"),
    ("ko/index.html", "ko", "../app/"),
    ("ga/index.html", "ga", "../app/"),
    ("app/index.html", "en", "./"),
]:
    locale = locales[language]
    title, description = escape(locale["title"], quote=True), escape(locale["description"], quote=True)
    url = ORIGIN + locale["path"]
    alternates = "\n".join(
        f'    <link rel="alternate" hreflang="{lang}" href="{ORIGIN}{item["path"]}">'
        for lang, item in locales.items()
    )
    (ROOT / route).write_text(f'''<!doctype html>
<!-- Generated by scripts/build-pages.py. Shared interface: app/shell.html. -->
<html lang="{language}">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
    <meta name="theme-color" content="#fbf4e8">
    <meta name="app-version" content="v0.9.2">
    <title>{title}</title>
    <meta name="description" content="{description}">
    <link rel="canonical" href="{url}">
{alternates}
    <link rel="alternate" hreflang="x-default" href="{ORIGIN}">
    <meta property="og:title" content="{title}">
    <meta property="og:description" content="{description}">
    <meta property="og:type" content="website">
    <meta property="og:url" content="{url}">
    <meta property="og:image" content="{IMAGE}">
    <meta property="og:image:type" content="image/png">
    <meta property="og:image:width" content="1734">
    <meta property="og:image:height" content="907">
    <meta property="og:site_name" content="{title}">
    <meta name="twitter:card" content="summary_large_image">
    <meta name="twitter:title" content="{title}">
    <meta name="twitter:description" content="{description}">
    <meta name="twitter:image" content="{IMAGE}">
    <link rel="stylesheet" href="{assets}styles.css">
  </head>
  <body>
    <noscript>Please enable JavaScript to use Goose Choose.</noscript>
    <script src="{assets}locales.js"></script>
    <script src="{assets}shell.js"></script>
    <script src="{assets}routes.js"></script>
    <script src="{assets}app.js"></script>
  </body>
</html>
''')
